vector<string> topKFrequent(vector<string>& words, int k) {
    unordered_map<string,int> c; for (auto& w : words) c[w]++;
    auto better = [&](const string& a, const string& b) { return c[a] != c[b] ? c[a] > c[b] : a < b; };
    priority_queue<string, vector<string>, decltype(better)> h(better);   // top = worst survivor
    for (auto& [w, n] : c) { h.push(w); if ((int)h.size() > k) h.pop(); }
    vector<string> out; while (!h.empty()) { out.push_back(h.top()); h.pop(); }
    reverse(out.begin(), out.end()); return out;
}
